{
  "id": 14,
  "knowledge": "Response Effectiveness Score (RES)",
  "description": "A composite score measuring the overall effectiveness of the response operation.",
  "definition": "A weighted score of an operation's success. Formula: (0.4 * success_rate) + (0.3 * bene_feedbackscore * 10) + (0.3 * distequityidx * 100)."
}

{
  "id": 25,
  "knowledge": "Condition Index Tiers",
  "description": "Translates the composite health index score into qualitative ratings of the robot's condition.",
  "definition": "A Condition Index is 'Excellent' if > 0.9, 'Good' if 0.7-0.9, 'Fair' if 0.5-0.7, or 'Poor' if < 0.5 (significant wear or risk)."
}

{
  "id": 1,
  "knowledge": "Payload Utilization Ratio (PUR)",
  "description": "Measures the ratio of the robot's actual working payload to its maximum rated payload capacity, indicating how heavily it is loaded.",
  "definition": "The proportion of the robot's maximum lifting capacity being used. Formula: actual_payload_weight / payload_capacity_kg."
}

{
  "id": 12,
  "knowledge": "Throughput Rate",
  "description": "Calculates the number of cycles completed per minute, as a direct measure of production throughput.",
  "definition": "The number of program cycles a robot completes per minute. Formula: 60 / cycle_time_seconds."
}
